describe('File Upload Success Checkmark', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display success checkmark when file upload completes successfully', () => {
    // Intercept the file upload API endpoint
    cy.intercept('POST', '/api/files/upload').as('fileUpload');

    // Get the file input element
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Verify file name is displayed
    cy.get('[data-testid="file-name-display"]').should('contain', 'sample.pdf');

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload API call
    cy.wait('@fileUpload').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success checkmark appears
    cy.get('[data-testid="success-checkmark"]').should('be.visible');
    cy.get('[data-testid="success-checkmark"]').should('have.class', 'success-icon');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');

    // Verify upload progress indicator is hidden
    cy.get('[data-testid="upload-progress-bar"]').should('not.exist');

    // Verify file is listed in uploaded files section
    cy.get('[data-testid="uploaded-file-list"]').should('contain', 'sample.pdf');
  });

  it('should not display success checkmark when file upload fails', () => {
    // Intercept the file upload API endpoint and mock a failure response
    cy.intercept('POST', '/api/files/upload', {
      statusCode: 500,
      body: { error: 'Server error during upload' }
    }).as('fileUploadFailure');

    // Get the file input element
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/large_file.zip', { force: true });

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the failed upload API call
    cy.wait('@fileUploadFailure');

    // Verify success checkmark does NOT appear
    cy.get('[data-testid="success-checkmark"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Upload failed');

    // Verify error details are shown
    cy.get('[data-testid="error-details"]').should('be.visible');
    cy.get('[data-testid="error-details"]').should('contain', 'Server error');

    // Verify upload progress indicator is still visible or shows error state
    cy.get('[data-testid="upload-progress-bar"]').should('be.visible');
    cy.get('[data-testid="upload-progress-bar"]').should('have.class', 'error-state');

    // Verify file is not listed in uploaded files section
    cy.get('[data-testid="uploaded-file-list"]').should('not.contain', 'large_file.zip');
  });
});
